CREATE VIEW "Z_TEST_PRODUCTION_20250925"."B1_PaymentMeansDateTotalsView" ( "PayObjType", "PayAbsEntry", "MeansType", "MeansLine", "MeansAbsEntry", "MeansID", "MeansStrID", "MeansDate", "MeansDateTotal", "DocTotalSum", "MeansPart" ) AS SELECT T0."PayObjType" AS "PayObjType", T0."PayAbsEntry" AS "PayAbsEntry", MAX(T0."MeansType") AS "MeansType", MIN(T0."MeansLine") AS "MeansLine", MIN(T0."MeansAbsEntry") AS "MeansAbsEntry", MIN(T0."MeansID") AS "MeansID", MIN(T0."MeansStrID") AS "MeansStrID", T0."MeansDate" AS "MeansDate", SUM(T0."MeansTotalSum") AS "MeansDateTotal", MAX(T0."DocTotalSum") AS "DocTotalSum", SUM(T0."MeansPart") AS "MeansPart" FROM  "Z_TEST_PRODUCTION_20250925"."B1_PaymentMeansView" T0  GROUP BY T0."PayObjType", T0."PayAbsEntry", T0."MeansDate" WITH READ ONLY